Clear[k,S,B₀,ℓ,v₀,t₀,R,t,τ];
S₁=ℓ*Integrate[v₀,{τ,t₀,t}];
Φ=k*t*S+B₀*S₁;
ε₁=D[Φ,t];
j₀=ε₁/R;
F=Simplify[B₀*ℓ*j₀];
Column[{
  Labeled[S₁, "swept area"],
  Labeled[Φ, "magnetic flux"],
  Labeled[ε₁, "induced EMF"],
  Labeled[j₀, "current"],
  Labeled[F, "required external force"]
}]

q₀={B₀->1,ℓ->1/2,v₀->2,k->1/5,S->3/10,R->2,t₀->1};
Column[{
  Labeled[UnitSimplify["T^2*m^3/(s*ohm)"], "force unit"],
  Labeled[ReplaceAll[F,q₀][N], "external force [N]"],
  Labeled[Plot[ReplaceAll[Φ,q₀],{t,1,4}], "magnetic flux versus time [Wb]"]
}]

Clear[a,x,p,q,u,v,g₁,p₉];
f=1/Sqrt[1+x]+1/Sqrt[1+a]+Sqrt[a*x/(a*x+8)];
f₈=ReplaceAll[f,a->8];
c₉=SolveValues[D[f₈,x]==0,x];
Column[{
  Labeled[Simplify[D[f₈,x]], "f₈ derivative"],
  Labeled[c₉, "stationary x values"],
  Labeled[Reduce[{D[f₈,x]>0,x>0},x,Reals], "increasing region"],
  Labeled[Reduce[{D[f₈,x]<0,x>0},x,Reals], "decreasing region"],
  Labeled[Table[Simplify[ReplaceAll[f₈,x->p]],{p,c₉}], "stationary function values"],
  Labeled[Plot[f₈,{x,1/100,8}], "f₈ versus x"]
}]

b₅=Sort[{Limit[ReplaceAll[f,a->x],x->0],Limit[ReplaceAll[f,a->x],x->Infinity]}];
s₁₂=Factor[Together[ReplaceAll[(f-1/Sqrt[1+x]-1/Sqrt[1+a])^2,{x->1/u^2-1,a->1/v^2-1}]]];
g₂={
  Together[ReplaceAll[s₁₂-(First[b₅]-u-v)^2,{u->p/(1+p+q),v->q/(1+p+q)}]],
  Together[ReplaceAll[(Last[b₅]-u-v)^2-s₁₂,{u->1-p/(1+p+q),v->1-q/(1+p+q)}]],
  Together[ReplaceAll[s₁₂,{u->p/(1+p),v->q/(1+q)}]],
  Together[ReplaceAll[1-s₁₂,{u->p/(1+p),v->q/(1+q)}]]
};
c₃=Table[Table[
  Min[Flatten[CoefficientList[p₉,{p,q}]]]>=0&&Max[Flatten[CoefficientList[p₉,{p,q}]]]>0,
  {p₉,{Numerator[g₁],Denominator[g₁]}}],{g₁,g₂}];
Column[{
  Labeled[b₅, "{infimum, supremum}"],
  Labeled[c₃, "strict-bound positivity checks"],
  Labeled[Plot3D[ReplaceAll[f,{a->Exp[p],x->Exp[q]}],{p,-8,8},{q,-8,8}], "f versus log(a), log(x)"]
}]

Clear[k,p,q];
t₂=Sum[(-1)^(k+1)/k,{k,1,1319}];
p=Numerator[t₂]; q=Denominator[t₂];
Column[{
  Labeled[N[t₂,30], "alternating harmonic sum, 30 digits"],
  Labeled[{IntegerLength[p],IntegerLength[q]}, "decimal digits, {numerator,denominator}"],
  Labeled[GCD[p,q], "GCD of numerator and denominator"],
  Labeled[{Mod[p,1979],Mod[q,1979]}, "remainders modulo 1979, {numerator,denominator}"],
  Labeled[p/1979, "exact numerator / 1979"]
}]

Clear[m,n,r₁₂];
b₄=120;
r₁₁=Table[PowerMod[1978,n,1000],{n,1,b₄}];
p₃=Flatten[Table[If[Part[r₁₁,m]==Part[r₁₁,n],{m,n},Nothing],{n,2,b₄},{m,1,n-1}],1];
b₂=Min[Table[Total[r₁₂],{r₁₂,p₃}]];
w₁=Table[If[Total[r₁₂]==b₂,Join[r₁₂,{Part[r₁₁,First[r₁₂]]}],Nothing],{r₁₂,p₃}];
Column[{
  Labeled[b₂, "minimum m+n"],
  Labeled[w₁, "{m,n,last three digits}"],
  Labeled[b₂<b₄+1, "search covers every smaller sum"],
  Labeled[ListPlot[Table[{n,Part[r₁₁,n]},{n,1,b₄}]], "1978^n modulo 1000"]
}]

Clear[x₁,y₁,x₂,y₂,h₁,h₂,u₃,u₄,t,τ,i,j,u];
m=1; k=40; l=1; g=981/100;
h₀=First[SolveValues[{k*(h₁-l)==2*m*g,k*(h₂-l)==m*g},{h₁,h₂}]];
r₀={0,Part[h₀,1],0,Total[h₀]};
q₁={x₁,y₁,x₂,y₂};
U=k/2*(Sqrt[x₁^2+y₁^2]-l)^2+k/2*(Sqrt[(x₂-x₁)^2+(y₂-y₁)^2]-l)^2-m*g*(y₁+y₂);
F=Table[-D[U,Part[q₁,i]]/m,{i,1,4}];
a₈={x₁->Part[r₀,1],y₁->Part[r₀,2],x₂->Part[r₀,3],y₂->Part[r₀,4]};
K=Simplify[Table[ReplaceAll[D[U,Part[q₁,i],Part[q₁,j]]/m,a₈],{i,1,4},{j,1,4}]];
Column[{
  Labeled[r₀, "equilibrium positions, {x₁,y₁,x₂,y₂} [m]"],
  Labeled[K, "stiffness / mass matrix [1/s^2]"],
  Labeled[Eigenvalues[K], "squared mode frequencies [1/s^2]"]
}]

u₀=DSolveValue[{
  u₃''[t]==-Part[K,1,1]*u₃[t]-Part[K,1,3]*u₄[t],
  u₄''[t]==-Part[K,3,1]*u₃[t]-Part[K,3,3]*u₄[t],
  u₃[0]==1/20,u₄[0]==3/25,u₃'[0]==0,u₄'[0]==0
},{u₃[t],u₄[t]},t];
Column[{
  Labeled[Part[u₀,1],"displacement, first ball"],
  Labeled[Part[u₀,2],"displacement, second ball"]
}]

q₂={x₁[t],y₁[t],x₂[t],y₂[t]};
t₁={x₁->x₁[t],y₁->y₁[t],x₂->x₂[t],y₂->y₂[t]};
e₁=Table[D[Part[q₂,i],{t,2}]==ReplaceAll[Part[F,i],t₁],{i,1,4}];
θ₁=60°; θ₂=-45°;
x₀={Part[h₀,1]*Sin[θ₁],Part[h₀,1]*Cos[θ₁],Part[h₀,1]*Sin[θ₁]+Part[h₀,2]*Sin[θ₂],Part[h₀,1]*Cos[θ₁]+Part[h₀,2]*Cos[θ₂]};
c₀=Flatten[Table[{ReplaceAll[Part[q₂,i],t->0]==Part[x₀,i],ReplaceAll[D[Part[q₂,i],t],t->0]==0},{i,1,4}],1];
r₁=NDSolveValue[Join[e₁,c₀],{x₁[t],y₁[t],x₂[t],y₂[t]},{t,0,6}];
Labeled[r₁, "large-angle position functions, {x₁,y₁,x₂,y₂} [m]"]

H=ReplaceAll[U,{x₁->Part[r₁,1],y₁->Part[r₁,2],x₂->Part[r₁,3],y₂->Part[r₁,4]}]+m/2*Total[Table[D[Part[r₁,i],t]^2,{i,1,4}]];
Column[{
  Labeled[Plot[u₀,{t,0,6},PlotLegends->{"第一球","第二球"}], "small-angle horizontal displacements [m]"],
  Labeled[Plot[{Part[r₁,1],Part[r₁,3]},{t,0,6},PlotLegends->{"第一球","第二球"}], "large-angle horizontal displacements [m]"],
  Labeled[Plot[H-ReplaceAll[H,t->0],{t,0,6}], "total energy drift [J]"]
}]

k₁=Table[{u*Part[r₁,1]+Sin[12*Pi*u]/30,-u*Part[r₁,2]},{u,0,1,1/30}];
k₂=Table[{(1-u)*Part[r₁,1]+u*Part[r₁,3]+Sin[12*Pi*u]/30,-(1-u)*Part[r₁,2]-u*Part[r₁,4]},{u,0,1,1/30}];
Labeled[Animate[Graphics[{
  Line[ReplaceAll[k₁,t->τ]],Line[ReplaceAll[k₂,t->τ]],
  Point[ReplaceAll[{{Part[r₁,1],-Part[r₁,2]},{Part[r₁,3],-Part[r₁,4]}},t->τ]]
}],{τ,0,6}], "large-angle motion, coordinates [m]"]

Clear[a₁,a₂,a₃,a₄,a₅,y₁,y₂,y₃,y₄,y₅,t,τ,i,u];
m=1; k=100; l=1; g=981/100; d₄=5;
r₀=First[SolveValues[{
  a₁==0,
  0==m*g+k*(a₃-2*a₂+a₁),
  0==m*g+k*(a₄-2*a₃+a₂),
  0==m*g+k*(a₅-2*a₄+a₃),
  0==m*g-k*(a₅-a₄-l)
},{a₁,a₂,a₃,a₄,a₅}]];
Labeled[r₀, "initial positions, balls 1...5 [m]"]

q₂={y₁[t],y₂[t],y₃[t],y₄[t],y₅[t]};
e₁={
  y₁''[t]==g+k/m*(y₂[t]-y₁[t]-l),
  y₂''[t]==g+k/m*(y₃[t]-2*y₂[t]+y₁[t]),
  y₃''[t]==g+k/m*(y₄[t]-2*y₃[t]+y₂[t]),
  y₄''[t]==g+k/m*(y₅[t]-2*y₄[t]+y₃[t]),
  y₅''[t]==g-k/m*(y₅[t]-y₄[t]-l)
};
c₀=Flatten[Table[{ReplaceAll[Part[q₂,i],t->0]==Part[r₀,i],ReplaceAll[D[Part[q₂,i],t],t->0]==0},{i,1,5}],1];
r₁=DSolveValue[Join[e₁,c₀],{y₁[t],y₂[t],y₃[t],y₄[t],y₅[t]},t];
Column[{
  Labeled[Part[r₁,1],"position, ball 1"],
  Labeled[Part[r₁,2],"position, ball 2"],
  Labeled[Part[r₁,3],"position, ball 3"],
  Labeled[Part[r₁,4],"position, ball 4"],
  Labeled[Part[r₁,5],"position, ball 5"]
}]

c₂=Simplify[Total[r₁]/5];
Column[{
  Labeled[Simplify[Table[ReplaceAll[D[Part[r₁,i],{t,2}],t->0],{i,1,5}]], "initial accelerations, balls 1...5 [m/s^2]"],
  Labeled[c₂, "center of mass position [m]"],
  Labeled[Series[Part[r₁,5],{t,0,10}], "bottom ball position series [m]"]
}]

b₃=Part[r₁,5]-Part[r₀,5];
n₂=Part[r₁,4]-Part[r₀,4];
f₁=g*t^2/2;
Column[{
  Labeled[Plot[{b₃,n₂,f₁},{t,0,d₄},PlotLegends->{"最下方小球","倒数第二个小球","自由落体"}], "bottom two balls and free-fall displacements [m]"],
  Labeled[Plot[{b₃-f₁,n₂-f₁,0},{t,0,d₄},PlotLegends->{"底球相对自由落体","次底球相对自由落体","自由落体（零基线）"}], "displacement differences from free fall [m]"]
}]

r₃=Table[Simplify[Part[r₁,i]-c₂],{i,1,5}];
c₆=Table[Table[{3/25*Sin[12*Pi*u],-(1-u)*Part[r₃,i]-u*Part[r₃,i+1]},{u,0,1,1/24}],{i,1,4}];
b₁=Table[{0,-Part[r₃,i]},{i,1,5}];
Labeled[Animate[Graphics[{
  Line[ReplaceAll[Part[c₆,1],t->τ]],Line[ReplaceAll[Part[c₆,2],t->τ]],
  Line[ReplaceAll[Part[c₆,3],t->τ]],Line[ReplaceAll[Part[c₆,4],t->τ]],
  Point[ReplaceAll[b₁,t->τ]]
}],{τ,0,d₄}], "spring chain, positions relative to center of mass [m]"]

Clear[x₁,y₁,x₂,y₂,x₃,y₃,x,y,t,τ,i,j,u];
q₁={x₁,y₁,x₂,y₂,x₃,y₃};
U=-1/Sqrt[(x₁-x₂)^2+(y₁-y₂)^2]-1/Sqrt[(x₁-x₃)^2+(y₁-y₃)^2]-1/Sqrt[(x₂-x₃)^2+(y₂-y₃)^2];
q₂={x₁[t],y₁[t],x₂[t],y₂[t],x₃[t],y₃[t]};
r₁₃={x₁->x₁[t],y₁->y₁[t],x₂->x₂[t],y₂->y₂[t],x₃->x₃[t],y₃->y₃[t]};
e₁=Table[D[Part[q₂,i],{t,2}]==ReplaceAll[-D[U,Part[q₁,i]],r₁₃],{i,1,6}];
p₀={-0.97000436,0.24308753,0.97000436,-0.24308753,0,0};
v₄={0.466203685,0.43236573,0.466203685,0.43236573,-0.93240737,-0.86473146};
c₀=Flatten[Table[{ReplaceAll[Part[q₂,i],t->0]==Part[p₀,i],ReplaceAll[D[Part[q₂,i],t],t->0]==Part[v₄,i]},{i,1,6}],1];
r₁=NDSolveValue[Join[e₁,c₀],{x₁[t],y₁[t],x₂[t],y₂[t],x₃[t],y₃[t]},{t,0,6.3259}];
Labeled[r₁, "position functions, {x₁,y₁,x₂,y₂,x₃,y₃}"]

H=ReplaceAll[U,{x₁->Part[r₁,1],y₁->Part[r₁,2],x₂->Part[r₁,3],y₂->Part[r₁,4],x₃->Part[r₁,5],y₃->Part[r₁,6]}]+Total[Table[D[Part[r₁,i],t]^2/2,{i,1,6}]];
p₁={Total[Table[D[Part[r₁,2*i-1],t],{i,1,3}]],Total[Table[D[Part[r₁,2*i],t],{i,1,3}]]};
L=Total[Table[Part[r₁,2*i-1]*D[Part[r₁,2*i],t]-Part[r₁,2*i]*D[Part[r₁,2*i-1],t],{i,1,3}]];
Column[{
  Labeled[Plot[H-ReplaceAll[H,t->0],{t,0,6.3259}], "total energy drift"],
  Labeled[Plot[p₁,{t,0,6.3259},PlotLegends->{"水平总动量","竖直总动量"}], "total momentum, {x,y}"],
  Labeled[Plot[L,{t,0,6.3259}], "total angular momentum"]
}]

ε=3/20;
B₁=-Total[Table[1/Sqrt[(x-Part[r₁,2*i-1])^2+(y-Part[r₁,2*i])^2+ε^2],{i,1,3}]];
Labeled[Animate[Plot3D[ReplaceAll[B₁,t->τ],{x,-2,2},{y,-3/2,3/2},PlotPoints->41,BoxRatios->{1,1,1/2}],{τ,0,6.3259}], "gravitational potential versus planar position"]

p₆={1,1,1,1};
p₇={{1,0},{0,1},{-1,0},{0,-1}};
p₈={{0,1},{-1,0},{0,-1},{1,0}};
p₅=NBodySolve[p₆,p₇,p₈,{t,0,4}];
Labeled[NBodyPlot3D[p₅,p₆,{t,0,4}],"four bodies, planar motion and gravitational potential; G=1"]

k₃=Total[Table[Part[s₇,i]/2*Total[Table[D[Part[s₆,i,j],t]^2,{j,1,3}]],{i,1,5}]];
U₁=-Total[Flatten[Table[Part[s₇,i]*Part[s₇,j]/Sqrt[Total[Table[(Part[s₆,i,k]-Part[s₆,j,k])^2,{k,1,3}]]],{i,1,4},{j,i+1,5}],1]];
H₁=k₃+U₁;
p₂=Table[Total[Table[Part[s₇,i]*D[Part[s₆,i,j],t],{i,1,5}]],{j,1,3}];
Column[{
  Labeled[Plot[H₁-ReplaceAll[H₁,t->0],{t,0,1.2}],"five-body total energy drift"],
  Labeled[Plot[p₂,{t,0,1.2},PlotLegends->{"px","py","pz"}],"five-body total momentum"]
}]

Clear[z,φ,x,y,t,i,j,h,r₁₂,s₂];
c₆={-0.7,0,0.7};
n₄=Total[Table[1/(1+h^2)^(3/2),{h,c₆}]];
a₁₀=Total[Table[1/(1+(z-h)^2)^(3/2),{h,c₆}]]/n₄;
r₇=0.1[m]; j₀=1000[A]; μ=4*Pi*1e-7[H/m];
c₄=1.602176634e-19[C]; m=1.67262192369e-27[kg];
c₂=μ*j₀/(2*r₇)*n₄;
τ₀=m/(c₄*c₂);
Column[{
  Labeled[a₁₀, "axial magnetic field, Bz(z) / B0"],
  Labeled[N[UnitConvert[c₂,"mT"],12], "central magnetic field B0"],
  Labeled[N[UnitConvert[τ₀,"us"],12], "time scale, mp / (e B0)"],
  Labeled[N[UnitConvert[r₇/τ₀,"km/s"],12], "velocity scale, R / time scale"]
}]

u₅=DSolveValue[{
  x''[t]==y'[t],y''[t]==-x'[t],z''[t]==0,
  x[0]==11/50,y[0]==0,z[0]==1/10,x'[0]==0,y'[0]==4/25,z'[0]==2/25
},{x[t],y[t],z[t]},t];
Column[{
  Labeled[Part[u₅,1],"uniform field, x(t)"],
  Labeled[Part[u₅,2],"uniform field, y(t)"],
  Labeled[Part[u₅,3],"uniform field, z(t)"]
}]

h₀=Table[Part[m₂,k,3],{k,1,6}];
s₁₁=Table[Total[Table[D[Part[m₂,k,i],t]^2,{i,1,3}]],{k,1,6}];
s₁₀=Table[Part[s₁₁,k]-ReplaceAll[Part[s₁₁,k],t->0],{k,1,6}];
Column[{
  Labeled[Plot[Join[{Part[u₅,3]},h₀],{t,0,20},PlotLegends->{"uniform, 1","1,+e","2,+e","3,+e","4,-e","5,-e","6,-e"}],"height, z/R"],
  Labeled[Plot[s₁₀,{t,0,20},PlotLegends->{"1,+e","2,+e","3,+e","4,-e","5,-e","6,-e"}],"speed squared drift, six particles"]
}]

Clear[r,z,k,ℓ,n,j,a,b,f,h,e,c,u,v,x,y,θ];
e=D[f[r],{r,2}]+2/r*D[f[r],r]+(2*z/r-k^2-ℓ*(ℓ+1)/r^2)*f[r];
Labeled[e==0,"radial Schrodinger equation, E=-k^2/2"]
Labeled[SolveValues[a*(a+1)==ℓ*(ℓ+1),a],"exponents at the origin"]

u=r^ℓ*Exp[-k*r]*h[r];
v=Simplify[(D[u,{r,2}]+2/r*D[u,r]+(2*z/r-k^2-ℓ*(ℓ+1)/r^2)*u)/(r^(ℓ-1)*Exp[-k*r])];
Labeled[Expand[v]==0,"equation for the remaining radial factor"]
u=a*r^j+b*r^(j+1);
v=Expand[r*D[u,{r,2}]+(2*ℓ+2-2*k*r)*D[u,r]+2*(z-k*(ℓ+1))*u];
c=Coefficient[PowerExpand[v/r^(j-1)],r,1];
Labeled[SolveValues[c==0,b],"coefficient recurrence: b=a_(j+1), a=a_j"]
k=First[SolveValues[z-k*(j+ℓ+1)==0,k]];
Labeled[k,"termination condition"]
Labeled[ReplaceAll[-k^2/2,j->n-ℓ-1],"bound-state energy"]

z=2;
a=Table[
 n=Part[b,1];ℓ=Part[b,2];k=z/n;
 c=Table[Product[2*(k*(j+ℓ+1)-z)/((j+1)*(j+2*ℓ+2)),{j,0,h-1}],{h,0,n-ℓ-1}];
 u=r^ℓ*Exp[-k*r]*Total[Table[Part[c,j+1]*r^j,{j,0,n-ℓ-1}]];
 v=Integrate[u^2*r^2,{r,0,Infinity}];
 Simplify[u/Sqrt[v]],
 {b,{{1,0},{2,0},{2,1},{3,0},{3,1},{3,2}}}];
Labeled[a,"normalized radial functions R_nl"]
Labeled[Table[Integrate[Part[a,j]^2*r^2,{r,0,Infinity}],{j,1,6}],"radial normalization"]
Labeled[Table[n=Part[b,1];ℓ=Part[b,2];u=Part[a,Part[b,3]];Simplify[-(D[u,{r,2}]+2/r*D[u,r]-ℓ*(ℓ+1)*u/r^2)/2-z/r*u+z^2/(2*n^2)*u],{b,{{1,0,1},{2,0,2},{2,1,3},{3,0,4},{3,1,5},{3,2,6}}}],"Schrodinger equation residuals"]

Clear[ℓ,k,n,j,h,z,q,b,c];
a₂=Table[
 h=b₀+b₁*q+b₂*q^2;
 v=Expand[(1-q^2)*D[h,{q,2}]-2*q*D[h,q]+ℓ*(ℓ+1)*h];
 c=First[Solve[Join[Table[Coefficient[v,q,j]==0,{j,0,2}],{If[ℓ==0,b₀,If[ℓ==1,b₁,b₂]]==1}],{b₀,b₁,b₂}]];
 Simplify[ReplaceAll[h,c]],{ℓ,0,2}];
Labeled[a₂,"angular polynomials from the separated equation"]
b=Table[
 ℓ=Part[c,1];u=Part[a,Part[c,2]];
 h=ReplaceAll[Part[a₂,ℓ+1],q->Cos[θ]];
 v=Simplify[h/Sqrt[2*Pi*Integrate[h^2*Sin[θ],{θ,0,Pi}]]];
 Simplify[ReplaceAll[u^2*v^2,{r->Sqrt[x^2+y^2+z^2],θ->ArcCos[z/Sqrt[x^2+y^2+z^2]]}]],
 {c,{{0,1},{0,2},{1,3},{0,4},{1,5},{2,6}}}];
Labeled[DensityPlot3D[Part[b,1],{x,-3,3},{y,-3,3},{z,-3,3}],"He+, 1s"]
Labeled[DensityPlot3D[Part[b,2],{x,-8,8},{y,-8,8},{z,-8,8}],"He+, 2s"]
Labeled[DensityPlot3D[Part[b,3],{x,-8,8},{y,-8,8},{z,-8,8}],"He+, 2p_z"]
Labeled[DensityPlot3D[Part[b,4],{x,-15,15},{y,-15,15},{z,-15,15}],"He+, 3s"]
